<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;Auth::requireAdmin();$pdo=Database::connection();$notice='';$error='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$action=(string)($_POST['action']??'');$eventId=(int)($_POST['event_id']??0);if($action==='reopen_scoring'){$s=$pdo->prepare("SELECT e.id,e.status,r.id round_id,r.scoring_mode,r.dance_style,r.division,r.round_type FROM bdc_events e JOIN bdc_scoring_rounds r ON r.event_id=e.id WHERE e.id=:event AND e.status='completed' ORDER BY FIELD(r.round_type,'final','semifinal','heats'),r.id DESC LIMIT 1");$s->execute(['event'=>$eventId]);$row=$s->fetch();if(!$row)throw new RuntimeException('Completed scoring workflow not found.');$pdo->beginTransaction();$pdo->prepare("UPDATE bdc_scoring_rounds SET status=CASE WHEN round_type='final' THEN 'scores_submitted' ELSE status END,locked_at=NULL,locked_by=NULL WHERE event_id=:event")->execute(['event'=>$eventId]);$pdo->prepare("UPDATE bdc_events SET status='published',updated_at=NOW() WHERE id=:event")->execute(['event'=>$eventId]);$audit=$pdo->prepare("INSERT INTO bdc_scoring_audit(round_id,user_id,action,details_json) VALUES(:round,:user,'completed_event_reopened',:details)");$audit->execute(['round'=>$row['round_id'],'user'=>(int)(Auth::user()['id']??0)?:null,'details'=>json_encode(['event_id'=>$eventId,'dance_style'=>$row['dance_style']??'bachata'],JSON_UNESCAPED_SLASHES)]);$pdo->commit();header('Location: '.url('admin/scoring/index.php?mode='.rawurlencode((string)$row['scoring_mode']).'&round_id='.(int)$row['round_id'].'&reopened=1'),true,303);exit;}}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
$events=$pdo->query("SELECT e.id,e.name,e.event_date,e.status,COUNT(r.id) rounds,MAX(r.updated_at) scoring_updated,MAX(CASE WHEN r.round_type='final' THEN r.id ELSE 0 END) final_round_id,GROUP_CONCAT(DISTINCT CONCAT(UPPER(LEFT(COALESCE(r.dance_style,'bachata'),1)),SUBSTRING(COALESCE(r.dance_style,'bachata'),2),' ',REPLACE(r.division,'_',' ')) ORDER BY r.dance_style,r.division SEPARATOR ', ') competitions FROM bdc_events e JOIN bdc_scoring_rounds r ON r.event_id=e.id LEFT JOIN bdc_scoring_archived_events a ON a.event_id=e.id WHERE e.status='completed' AND a.event_id IS NULL GROUP BY e.id,e.name,e.event_date,e.status ORDER BY COALESCE(e.event_date,'1900-01-01') DESC,e.id DESC")->fetchAll();$csrf=Csrf::token();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Completed Events | BDC Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../">BDC Admin</a><div class="d-flex gap-2"><a class="btn btn-outline-light btn-sm" href="../">Dashboard</a><a class="btn btn-outline-light btn-sm" href="../archived-events/">Archived Events</a></div></div></nav><main class="container py-4" style="max-width:1250px"><div class="mb-4"><h1 class="h3 mb-1">Completed Events</h1><p class="text-muted mb-0">Published and approved competitions leave the active Scoring Dashboard automatically. Open Scoring only when an amendment is required.</p></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card shadow-sm border-0"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Event</th><th>Date</th><th>Competition</th><th>Rounds</th><th>Last Scoring Update</th><th class="text-end">Action</th></tr></thead><tbody><?php if(!$events):?><tr><td colspan="6" class="text-center text-muted py-5">No completed events.</td></tr><?php else:foreach($events as $event):?><tr><td><strong><?=e($event['name'])?></strong><div class="small text-success">Completed</div></td><td><?=e($event['event_date']?:'Date pending')?></td><td><?=e(ucwords((string)$event['competitions']))?></td><td><?=(int)$event['rounds']?></td><td><?=e((string)$event['scoring_updated'])?></td><td class="text-end"><form method="post" onsubmit="return confirm('Reopen the existing scoring workflow for amendment? This does not create a new event or duplicate scoring round. The scorer must resubmit it for Admin approval after changes.');"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="reopen_scoring"><input type="hidden" name="event_id" value="<?=(int)$event['id']?>"><button class="btn btn-outline-primary btn-sm">Open Scoring</button></form></td></tr><?php endforeach;endif;?></tbody></table></div></div></main></body></html>